(()=>{'use strict';const scenes={spring:{label:'春 · 桃花',description:'花枝停在水边，浅水里有缓慢游过的春天。'},summer:{label:'夏 · 清浅',description:'透亮的浅绿，缓缓流过的水光。夏天不必那么热闹。'},autumn:{label:'秋 · 桂影',description:'桂花与暖色水光，中央沙床渐渐过渡到池边。'}};let active='summer';const $=id=>document.getElementById(id),frame=$('live-demo'),region=$('demo-region');function choose(season){active=season;const s=scenes[season];document.querySelectorAll('[data-season]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.season===season)));$('pond-image').src='assets/'+season+'.png';$('pond-image').alt=s.label+' · 当前候选版真实预览';$('scene-label').textContent=s.label;$('scene-description').textContent=s.description;if(!region.hidden)frame.src='demo/'+season+'/';}document.querySelectorAll('[data-season]').forEach(b=>b.addEventListener('click',()=>choose(b.dataset.season)));$('open-demo').addEventListener('click',()=>{region.hidden=false;frame.src='demo/'+active+'/';$('open-demo').setAttribute('aria-expanded','true');region.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'start'});});$('close-demo').addEventListener('click',()=>{frame.removeAttribute('src');region.hidden=true;$('open-demo').setAttribute('aria-expanded','false');$('open-demo').focus();});$('open-demo').setAttribute('aria-controls','demo-region');$('open-demo').setAttribute('aria-expanded','false');})();
